function lampChargeCue(world){
  let inside=-1, retained=-1, best=0;
  for(let index=0;index<world.lamps.length;index++){
    const lamp=world.lamps[index];
    if(lamp.lit)continue;
    const dx=world.player.x-lamp.x,dy=world.player.y-lamp.y;
    if(Math.hypot(dx,dy)<75){inside=index;break;}
    if(lamp.progress>best){retained=index;best=lamp.progress;}
  }
  if(inside>=0){
    const remaining=Math.max(1,Math.ceil((3-world.lamps[inside].progress)*10-1e-8))/10;
    return ` · 灯${inside+1} 点亮还需${remaining.toFixed(1)}秒`;
  }
  if(retained>=0){
    const charge=Math.floor(best*10+1e-8)/10;
    return ` · 暂离灯${retained+1} 已蓄${charge?charge.toFixed(1):"不足0.1"}秒（回退）`;
  }
  return "";
}
